foundation.question_text:
Write the interval notation for a number line showing a closed dot at $1$ with an arrow pointing to the right.
[tikz]
\begin{tikzpicture}
\draw[{Stealth}-{Stealth}] (-2.9,0)--(2.9,0);
\foreach \x in {-5,...,5} {\draw (0.5*\x,0.12)--(0.5*\x,-0.12); \node[below] at (0.5*\x,-0.16) {\x};}
\draw[very thick,-{Stealth}] (0.5,0)--(2.7,0);
\fill (0.5,0) circle (2.4pt);
\node[right] at (3,0) {$x$};
\end{tikzpicture}
[/tikz]

Write the interval notation for a number line showing an open dot at $-3$ with an arrow pointing to the left.
[tikz]
\begin{tikzpicture}
\draw[{Stealth}-{Stealth}] (-2.9,0)--(2.9,0);
\foreach \x in {-5,...,5} {\draw (0.5*\x,0.12)--(0.5*\x,-0.12); \node[below] at (0.5*\x,-0.16) {\x};}
\draw[very thick,-{Stealth}] (-1.5,0)--(-2.7,0);
\draw[fill=white] (-1.5,0) circle (2.4pt);
\node[right] at (3,0) {$x$};
\end{tikzpicture}
[/tikz]

development.question_text:
Write the interval notation for a number line showing an open dot at $-2$ connected by a shaded line to a closed dot at $4$.
[tikz]
\begin{tikzpicture}
\draw[{Stealth}-{Stealth}] (-2.9,0)--(2.9,0);
\foreach \x in {-5,...,5} {\draw (0.5*\x,0.12)--(0.5*\x,-0.12); \node[below] at (0.5*\x,-0.16) {\x};}
\draw[very thick] (-1,0)--(2,0);
\draw[fill=white] (-1,0) circle (2.4pt);
\fill (2,0) circle (2.4pt);
\node[right] at (3,0) {$x$};
\end{tikzpicture}
[/tikz]
